head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.STD_CD_APPL_ID = "";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 표준코드 처리자 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    let queryId = "";
    // 표준코드 처리자 조회 팝업이다.
    // param1 => 표준코드 STD_CD

    // alert(frame.Provider("../").vScrenID);

    if ($c.frame.path("../").scwin.vScrenID === "ULDINS15900.gfm") {
        queryId = "lds.ins.common.select.listStdCdINDICPrcInquiry"; // 지표일경우

    } else if ($c.frame.path("../").scwin.vScrenID === "ULDINS15400.gfm") {
        queryId = "lds.ins.common.select.listStdCdFUTOPTPrcInquiry"; // 선물옵션일경우

    } else {
        queryId = "lds.ins.common.select.listStdCdPrcInquiry";
    }
    // alert(queryId);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = scwin.STD_CD_APPL_ID;
    scwin.arrPar[1] = "STD_CD";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    const arrPar = new Array();
    const parentWin = $c.frame.path("../");
    let fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar !== undefined) {
        fn_GetPar(scwin.arrPar);
        scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] !== undefined) ? scwin.arrPar[0] : "");
        //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

        await scwin.ins_search();
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row === 0) return;
    scwin.STD_CD_APPL_ID = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD_APPL_ID"); // 발행기관  신청 ID
    if (scwin.STD_CD_APPL_ID === "접수번호없음") return;
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS93600", "신청인정보", "620", "410");
};
